const $=id=>document.getElementById(id);let data={},markets={},mode='replay',live=false,generation=0,resume=null;
function describe(v){if(v==null)return '';if(Array.isArray(v))return v.map(describe).filter(Boolean).join(' · ');if(typeof v==='object')return Object.entries(v).filter(([k,x])=>x!=null&&x!=='').map(([k,x])=>k.replaceAll('_',' ')+': '+describe(x)).join(' · ');return String(v);}
const esc=s=>describe(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatMoney=n=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n):'Unknown';
const link=(u,label,cls='')=>{try{const p=new URL(u);if(!['http:','https:'].includes(p.protocol))return '';return `<a class="${cls}" href="${esc(p.href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}catch{return ''}};
function render(d){const money=n=>formatMoney(n);if(d.url)$('eventUrl').value=d.url;$('results').hidden=false;$('results').innerHTML=`<div class="result-heading"><div><span class="eyebrow">${mode==='replay'?'SAVED ZOOWORK RESEARCH · OCT 4, 2026':'LIVE AGENT RESULT'}</span><h2>${esc(d.title)}</h2><p>${esc(typeof d.meta==='object'&&d.meta?['location','city','date','time','category'].map(k=>d.meta[k]).filter(Boolean).map(describe).join(' · '):d.meta)}</p></div><span class="chip">${d.code?'Source-confirmed':d.kind==='claim_route'?'Claim route · availability unconfirmed':'Discovery'}</span></div>${d.kind==='claim_route'?`<div class="claim-route"><div><span class="eyebrow">${esc(d.discount)}</span><h3>Check your eligible coupons on the platform.</h3><p>${esc(d.note)}</p>${link(d.source,d.sourceLabel||'Official rules')}<p>${link(d.url,'Open platform')}</p><span class="chip">No coupon claimed · savings unknown</span></div><div><h3>Your next steps</h3><ol>${(d.claimSteps||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div></div>`:d.code?`<div class="result-grid"><div class="receipt"><span class="eyebrow">YOUR POTENTIAL WAY IN</span><div class="price-line">${d.final!=null?`<del>${money(d.base)}</del><strong>${money(d.final)}</strong>`:`<strong>${d.base!=null?money(d.base):'Price unknown'}</strong>`}</div><div class="saving"><b>${d.saving!=null?'Save '+money(d.saving):esc(d.discount)}</b><small>${d.final!=null?'Estimated ticket price · before fees':'Discount amount not confirmed'}</small></div><p class="fineprint">${esc(d.note)}</p></div><div class="codecard"><span class="eyebrow">THE PUBLIC OFFER</span><h3>${esc(d.discount)}</h3><div class="codebox"><code>${esc(d.code)}</code><button class="copybtn" data-copy="${esc(d.code)}">Copy code</button></div><p class="details"><span class="chip">Publicly published</span> <span class="chip">Checkout unverified</span></p><p class="evidence">${link(d.source,d.sourceLabel||'See offer source')}</p>${link(d.checkout,'Open ticket page','cta')}</div></div>`:`<div class="callout"><h3>No public code confirmed for this link.</h3><p>${esc(d.note)}</p>${link(d.url,'View original event')}</div>`}${d.alternatives?.length?`<div class="alt-heading"><h3>A different way to get out there.</h3><span>Related events · clearly labeled dates</span></div><div class="alternatives">${d.alternatives.map(a=>`<article class="alt"><span class="chip">${esc(a.discount)}</span><h4>${esc(a.title)}</h4><p>${esc(a.meta)}</p>${a.final!=null?`<div class="alt-price"><del>${money(a.base)}</del> ${money(a.final)} estimated</div>`:''}${a.code?`<div class="codebox"><code>${esc(a.code)}</code><button class="copybtn" data-copy="${esc(a.code)}">Copy</button></div>`:''}<p>${esc(a.note)}</p><div class="source">${link(a.source,'Offer source')} · ${link(a.checkout,'Ticket page')}</div></article>`).join('')}</div>`:''}<details class="research-log"><summary>See the research trail</summary><div class="log-body">${(d.trace||[]).map(t=>`<p>✓ ${esc(t)}</p>`).join('')}<p>No tickets purchased. Source confirmation is separate from checkout verification.</p></div></details>`;}
function fail(s){$('error').hidden=false;$('error').textContent=s;}
function setMode(m){if(!$('progress').hidden&&m!==mode){generation++;$('progress').hidden=true;$('snatchButton').disabled=false;}if(m==='live'&&!live){fail('Live search runs through the local demo server. Open http://127.0.0.1:8765 on the demo computer. This hosted demo replays saved research.');return;}mode=m;$('error').hidden=true;['replay','live'].forEach(x=>$(x+'Mode').setAttribute('aria-pressed',x===m));$('modeLabel').textContent=m==='live'?'Live source research':'Recorded research · Oct 4, 2026';$('modeHint').textContent=m==='live'?'Live research checks public web sources, verifies offer terms and finds alternatives when needed. Usually takes 2–5 minutes.':live?'Replay saved ZooWork research. This is not a new search or checkout verification.':'Saved ZooWork research from October 4, 2026. Choose an example below; this page cannot search new links or verify checkout.';}
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const v=await r.json();if(!r.ok)throw Error(v.error||'Search failed');return v;}
function progress(i,text){$('progressFill').style.width=(i+1)*25+'%';[...$('stageList').children].forEach((s,j)=>s.classList.toggle('active',j<=i));$('activity').textContent=text;}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function run(){const token=++generation;$('error').hidden=true;$('results').hidden=true;$('progress').hidden=false;$('snatchButton').disabled=true;$('progressLabel').textContent=mode==='live'?'SEARCHING WITH ZOOWORK':'REPLAYING A SAVED RUN';try{if(mode==='replay'){const u=$('eventUrl').value.replace(/\/$/,'');const d=Object.values(data).find(x=>x.url.replace(/\/$/,'')===u);if(!d)throw Error('This link has no saved run. Choose one of the three examples, or use Live search on the local demo.');for(let i=0;i<4;i++){if(token!==generation)return;progress(i,d.trace[i]);await pause(650);}if(token===generation)render(d);}else{progress(0,'Starting a real research session…');const session=resume?{id:resume}:await api('/api/start',{url:$('eventUrl').value,interests:$('interests').value,eligibility:$('eligibility').value,category:$('category').value});resume=null;let cursor='',texts=[],count=0;for(let i=0;i<200&&token===generation;i++){const page=await api('/api/events?session='+encodeURIComponent(session.id)+'&cursor='+encodeURIComponent(cursor));cursor=page.cursor||cursor;for(const e of page.events){if(e.type==='tool'){count++;progress(Math.min(2,Math.floor(count/5)),'Checking public sources · '+count+' tool calls');}if(e.type==='text')texts.push(e.text);if(e.type==='finished'){if(e.outcome==='failed')throw Error('ZooWork research failed. Retry or use a saved example.');const t=texts.join('\n');const match=t.match(/```json\s*([\s\S]*?)```/);let d;try{d=JSON.parse(match?match[1]:t)}catch{}if(d?.title&&Array.isArray(d.trace)){d.market='US';d.currency='USD';render(d);}else{$('results').hidden=false;$('results').innerHTML='<div class="result-heading"><h2>Live research result</h2><span class="chip">Checkout unverified</span></div><pre class="raw"></pre>';$('results').querySelector('pre').textContent=t||'No research response returned.';}return;}}await pause(2500);}if(token===generation)throw Error('Search is still running. Session '+session.id+'. Try again later; use Saved demo for your presentation.');}}catch(e){fail(e.message);}finally{if(token===generation){$('progress').hidden=true;$('snatchButton').disabled=false;}}}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();run()});$('replayMode').onclick=()=>setMode('replay');$('liveMode').onclick=()=>setMode('live');$('stopButton').onclick=()=>{generation++;$('progress').hidden=true;$('snatchButton').disabled=false;fail('Stopped displaying this search. A started ZooWork run may continue using credits.');};document.querySelector('.examples').addEventListener('click',e=>{const b=e.target.closest('[data-example]');if(!b)return;setMode('replay');$('eventUrl').value=data[b.dataset.example].url;run()});document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copy);$('toast').textContent='Code copied';$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,1800)}catch{fail('Clipboard unavailable. Select and copy the displayed code.')}});
function renderDirectory(){const category=$('category').value;const list=(markets.US||[]).filter(x=>category==='All'||x.categories.includes(category));$('directoryCount').textContent='United States · '+list.length+' sources';$('marketNote').textContent='Check public codes, selected-event offers and member deals. Cashback is separate from an immediate ticket or checkout discount.';$('sourceDirectory').innerHTML=list.map(x=>`<article class="source-card"><span class="chip">${esc(x.status)}</span><h3>${esc(x.name)}</h3><div class="source-type">${esc(x.type)}</div><p>${esc(x.note)}</p><p class="access">${esc(x.access)}</p><div class="source-links">${link(x.url,'Open site')}${link(x.evidence,'Evidence')}</div>${live?`<button data-source="${esc(x.id)}">Use this source</button>`:''}</article>`).join('');}
$('category').onchange=renderDirectory;$('sourceDirectory').addEventListener('click',e=>{const b=e.target.closest('[data-source]');if(!b)return;const src=markets.US.find(x=>x.id===b.dataset.source);$('eventUrl').value=src.url;setMode('live');$('eventUrl').focus();});
(async()=>{data=await(await fetch('demo-data.json')).json();markets=await(await fetch('markets.json')).json();try{const config=await api('/api/config');live=config.live;}catch{}if(live){$('introCopy').textContent='Find public offers for events, dining and travel across the United States. Paste a link to get started.';}else{$('liveMode').style.display='none';$('eventUrl').readOnly=true;$('eventUrl').title='Choose one of the three saved examples below';document.querySelector('label[for="eventUrl"]').textContent='SAVED EVENT LINK';$('snatchButton').textContent='Replay this case ✳';document.querySelector('.preferences').style.display='none';$('modeHint').textContent='Saved ZooWork research from October 4, 2026. Choose an example below; this page cannot search new links or verify checkout.';}renderDirectory();render(data.robotics);const params=new URLSearchParams(location.search);if(params.has('market')){if(params.get('market')!=='US')params.delete('session');params.delete('market');history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():''));}const sid=params.get('session');if(live&&sid){resume=sid;setMode('live');run();}if(navigator.modelContext?.registerTool)navigator.modelContext.registerTool({name:'replay_saved_research',description:'Display one of three saved United States research examples; does not start live research.',inputSchema:{type:'object',properties:{example:{type:'string',enum:['robotics','art','fallback']}},required:['example'],additionalProperties:false},execute:async({example})=>{if(!data[example])throw Error('Unknown example');setMode('replay');$('eventUrl').value=data[example].url;render(data[example]);return{content:[{type:'text',text:'Displayed saved research for '+data[example].title}]}}});})();
